#include <vector>
#include <algorithm>

int main() {
    std::vector<int> v1(1000000);
    std::vector<int> v2(10);

    // Efficient O(1) swap of internal state
    using std::swap;
    swap(v1, v2);

    // v1.size() is now 10, v2.size() is now 1000000
    // This operation is guaranteed non-throwing and fast.

    // Swap trick to reduce capacity to zero
    std::vector<int>().swap(v1); 
    // v1 is now empty and capacity is minimized
}
